SELECT COUNT(*) FROM assessmentbasics ab 
JOIN assessmentsocialanddiagnosis asd ON asd.asd_key = ab.ab_key 
WHERE LOWER(asd.rec_status) = 'stable';

SELECT to.tx_out_key, to.tx_ref, to.tx_goal_stat, to.rec_goal_stat, to.txprogmet->>'Func_Impv' as func_improv
FROM treatmentoutcomes to
LIMIT 5;

SELECT t.tx_out_key, t.tx_ref, t.tx_goal_stat, t.rec_goal_stat, t.txprogmet->>'Func_Impv' as func_improv
FROM treatmentoutcomes t
LIMIT 5;
